from src.filter import drop_empty


def test_drop_empty_removes_all_empty_rows():
    rows = [["a", "b"], ["", ""], ["c", "d"]]
    assert drop_empty(rows) == [["a", "b"], ["c", "d"]]


def test_drop_empty_keeps_row_with_some_non_empty_cells():
    rows = [["", "b"], ["", ""]]
    assert drop_empty(rows) == [["", "b"]]


def test_drop_empty_handles_empty_rows_list():
    assert drop_empty([]) == []
